// first index i with a[i] >= x
int lowerBound(vector<int>& a, int x) {
    int lo = 0, hi = (int)a.size();
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (a[mid] < x) lo = mid + 1;
        else hi = mid;
    }
    return lo;
}

bool ok(vector<int>& w, int days, int cap) {
    int d = 1, cur = 0;
    for (int x : w) { if (cur + x > cap) d++, cur = 0; cur += x; }
    return d <= days;
}
int solve(vector<int>& w, int days) {
    int lo = 0, hi = 0;
    for (int x : w) lo = max(lo, x), hi += x;
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (ok(w, days, mid)) hi = mid; else lo = mid + 1;
    }
    return lo;
}
